	,spawnEnemies: function(deltaTime) {
		if(this.isBoss) {
			if(this.bossList.length > 0) {
				if(this.timeUntilSpawn > 0) this.timeUntilSpawn -= deltaTime; else {
					if(this.numberOfBossesOnStage >= 2) return;
					this.timeUntilSpawn = this.levelModelRef.minionSpawnInterval * 10;
					var nextEnemy = Type.createInstance(this.bossList.shift(),[10]);
					nextEnemy.build();
					if(this.lastBossLifebarConnected == this.bossLifeBar) {
						this.lastBossLifebarConnected = this.bossLifeBarPrissy;
						nextEnemy.connectLifebar(this.bossLifeBarPrissy);
						this.bossLifeBarPrissy.build(nextEnemy,this.bossPortraitList.shift());
						this.bossLifeBarPrissy.set_visible(true);
					} else {
						this.lastBossLifebarConnected = this.bossLifeBar;
						nextEnemy.connectLifebar(this.bossLifeBar);
						this.bossLifeBar.build(nextEnemy,this.bossPortraitList.shift());
						this.bossLifeBar.set_visible(true);
					}
					this.progressFrame.addProgress();
					this.numberOfBossesOnStage++;
				}
			}
			return;
		}
		if(this.spawnArrayRef.length <= 0) return;
		if(this.timeUntilSpawn > 0) this.timeUntilSpawn -= deltaTime; else {
			this.timeUntilSpawn = this.levelModelRef.minionSpawnInterval;
			if(this.isTutorial) {
				if(this.spawnArrayRef.length > 1) {
					var nextSpawnHealth = this.spawnArrayRef.shift();
					if(nextSpawnHealth != 0) {
						var nextEnemy1 = Type.createInstance(this.levelModelRef.minionType,[nextSpawnHealth]);
						nextEnemy1.build();
						nextEnemy1.canSpawnItems = true;
						this.progressFrame.addProgress();
					}
				}
			} else if(this.spawnArrayRef.length > 1) {
				var nextSpawnHealth1 = this.spawnArrayRef.shift();
				if(nextSpawnHealth1 != 0) {
					var nextEnemy2 = Type.createInstance(this.levelModelRef.minionType,[nextSpawnHealth1]);
					nextEnemy2.build();
					nextEnemy2.canSpawnItems = true;
					this.progressFrame.addProgress();
				}
			} else {
				this.spawnArrayRef.shift();
				var nextEnemy3 = Type.createInstance(this.levelModelRef.bossType,[10]);
				nextEnemy3.build();
				nextEnemy3.connectLifebar(this.bossLifeBar);
				this.bossLifeBar.build(nextEnemy3,this.levelModelRef.bossPortrait);
				this.bossLifeBar.set_visible(true);
			}
		}
	}
